export function construirTextoSemanticoCancion(cancion) {
  const extractoLetra = (cancion.letra || "").slice(0, 350).replace(/\s+/g, " ");
  return `title: ${cancion.titulo} - ${cancion.artista} | text: Canción "${cancion.titulo}" de ${cancion.artista} (${cancion.anio}). Género: ${cancion.categoria}. Ambiente: ${cancion.mood}. Descripción: ${cancion.descripcion}. Fragmento de letra: ${extractoLetra}`;
}
